PRAGMA foreign_keys = ON;
CREATE TABLE state_revision (id INTEGER PRIMARY KEY CHECK(id = 1), revision INTEGER NOT NULL);
INSERT INTO state_revision VALUES(1, 0);
CREATE TABLE transaction_guard (id TEXT PRIMARY KEY, valid INTEGER NOT NULL CHECK(valid = 1));
CREATE TABLE namespaces (name TEXT PRIMARY KEY CHECK(name NOT IN ('local','prosegate','core')), owner_id TEXT UNIQUE NOT NULL);
CREATE TABLE orgs (id TEXT PRIMARY KEY, namespace TEXT UNIQUE NOT NULL REFERENCES namespaces(name), name TEXT NOT NULL, policy_json TEXT NOT NULL DEFAULT '{}', signature TEXT, etag TEXT);
CREATE TABLE accounts (id TEXT PRIMARY KEY, auth_subject TEXT UNIQUE NOT NULL, namespace TEXT UNIQUE NOT NULL REFERENCES namespaces(name), plan TEXT NOT NULL DEFAULT 'free' CHECK(plan IN ('free','paid')), org_id TEXT REFERENCES orgs(id), default_profile TEXT, publisher INTEGER NOT NULL DEFAULT 0 CHECK(publisher IN (0,1)), flagged INTEGER NOT NULL DEFAULT 0);
CREATE TABLE org_members (org_id TEXT NOT NULL REFERENCES orgs(id), account_id TEXT NOT NULL REFERENCES accounts(id), role TEXT NOT NULL CHECK(role IN ('admin','member')), PRIMARY KEY(org_id,account_id));
CREATE TABLE devices (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), name TEXT NOT NULL, key_hash TEXT UNIQUE NOT NULL, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL, revoked_at INTEGER);
CREATE INDEX devices_account ON devices(account_id);
CREATE TABLE device_codes (code_hash TEXT PRIMARY KEY, user_code_hash TEXT UNIQUE NOT NULL, name TEXT NOT NULL, platform TEXT NOT NULL, adapter_version TEXT NOT NULL, account_id TEXT REFERENCES accounts(id), expires_at INTEGER NOT NULL, next_poll INTEGER NOT NULL, claimed_at INTEGER);
CREATE TABLE request_limits (bucket TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE profiles (id TEXT PRIMARY KEY, namespace TEXT NOT NULL REFERENCES namespaces(name), version INTEGER NOT NULL, name TEXT NOT NULL, yaml TEXT NOT NULL, signature TEXT NOT NULL, etag TEXT NOT NULL, parent_id TEXT REFERENCES profiles(id) ON DELETE RESTRICT, sharing_enabled INTEGER NOT NULL DEFAULT 0 CHECK(sharing_enabled IN (0,1)), updated_at INTEGER NOT NULL);
CREATE INDEX profiles_namespace ON profiles(namespace);
CREATE TABLE profile_versions (id TEXT NOT NULL, version INTEGER NOT NULL, yaml TEXT NOT NULL, signature TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE publishers (pack_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id));
CREATE TABLE rule_packs (id TEXT NOT NULL REFERENCES publishers(pack_id), version TEXT NOT NULL, publisher_id TEXT NOT NULL REFERENCES accounts(id), yaml TEXT NOT NULL, signature TEXT NOT NULL, eval_report_json TEXT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE publish_jobs (id TEXT PRIMARY KEY, pack_id TEXT NOT NULL, version TEXT NOT NULL, publisher_id TEXT NOT NULL REFERENCES accounts(id), yaml TEXT NOT NULL, content_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','running','passed','failed')), lease_until INTEGER, lease_token_hash TEXT, report_json TEXT, created_at INTEGER NOT NULL, UNIQUE(pack_id,version));
CREATE TABLE reviewer_prompts (version TEXT PRIMARY KEY, text TEXT NOT NULL, signature TEXT NOT NULL, supported_models_json TEXT NOT NULL);
CREATE TABLE reviewer_keys (key_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), device_id TEXT NOT NULL REFERENCES devices(id), provider TEXT NOT NULL CHECK(provider IN ('openai','anthropic')), project_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('provisioning','active','suspended','revoking','revoked')), cap_cents INTEGER NOT NULL, usage_cents INTEGER NOT NULL DEFAULT 0, daily_cents INTEGER NOT NULL DEFAULT 0, trailing_daily_cents REAL NOT NULL DEFAULT 0, polled_at INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL);
CREATE UNIQUE INDEX one_live_key_per_device ON reviewer_keys(device_id) WHERE status != 'revoked';
CREATE TABLE telemetry_outbox (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, device_id TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE telemetry_events (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, device_id TEXT NOT NULL, ts INTEGER NOT NULL, event_json TEXT NOT NULL);
CREATE INDEX telemetry_ts ON telemetry_events(ts);
CREATE TABLE telemetry_daily (account_id TEXT NOT NULL, day TEXT NOT NULL, profile_id TEXT NOT NULL, category TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(account_id,day,profile_id,category));
CREATE TABLE aggregate_days (day TEXT PRIMARY KEY, processed_at INTEGER NOT NULL);
CREATE TABLE samples (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), device_id TEXT NOT NULL REFERENCES devices(id), profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, pass INTEGER NOT NULL, excerpt TEXT NOT NULL, finding_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX samples_account ON samples(account_id,created_at);
CREATE TABLE idempotency (scope TEXT NOT NULL, key_hash TEXT NOT NULL, request_hash TEXT NOT NULL, response_status INTEGER NOT NULL, response_body TEXT, response_headers TEXT NOT NULL, expires_at INTEGER NOT NULL, PRIMARY KEY(scope,key_hash));
CREATE TABLE audit_log (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE TABLE notifications (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, code TEXT NOT NULL, target TEXT NOT NULL, created_at INTEGER NOT NULL, delivered_at INTEGER);
